import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.DaGSOal_.js";const u=JSON.parse('{"title":"Privacy","description":"Hosting, essential site functionality and privacy information for Deblx Documentation.","frontmatter":{"title":"Privacy","description":"Hosting, essential site functionality and privacy information for Deblx Documentation."},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md","lastUpdated":1794046641000}'),n={name:"privacy.md"};function i(s,e,c,l,d,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h1><p>Deblx Documentation is a static website for Unreal Engine plugin guides. Our main privacy policy is available at <strong><a href="https://deblx.com/privacy-policy" target="_blank" rel="noreferrer">deblx.com/privacy-policy</a></strong>.</p><h2 id="hosting-–-github-pages" tabindex="-1">Hosting – GitHub Pages <a class="header-anchor" href="#hosting-–-github-pages" aria-label="Permalink to &quot;Hosting – GitHub Pages&quot;">​</a></h2><p>The documentation is built with VitePress and published on <strong>GitHub Pages</strong>, a hosting service provided by GitHub, Inc. Accessing the website involves communication with the hosting infrastructure, including the processing of technical connection information such as IP addresses.</p><p>See the <a href="https://deblx.com/privacy-policy" target="_blank" rel="noreferrer">Deblx Privacy Policy</a> for general information and contact details.</p><h2 id="cloudflare" tabindex="-1">Cloudflare <a class="header-anchor" href="#cloudflare" aria-label="Permalink to &quot;Cloudflare&quot;">​</a></h2><p>Cloudflare manages the DNS for <code>docs.deblx.com</code>. When the DNS record is set to <strong>DNS only</strong>, browsers connect directly to GitHub Pages rather than passing through Cloudflare&#39;s HTTP proxy. If Cloudflare&#39;s proxy is enabled later, Cloudflare may additionally process technical requests to deliver and protect the website.</p><p>Depending on the enabled protection features, Cloudflare may use necessary security cookies such as <code>__cf_bm</code> (bot protection) or <code>cf_clearance</code> (security challenges). These cookies are <strong>not necessarily set on every visit</strong>. Their use depends on the actual domain, proxy configuration and activated protection rules.</p><p>For details, see <a href="https://developers.cloudflare.com/fundamentals/reference/policies-compliances/cloudflare-cookies/" target="_blank" rel="noreferrer">Cloudflare&#39;s cookie documentation</a> and the <a href="https://deblx.com/privacy-policy" target="_blank" rel="noreferrer">Deblx Privacy Policy</a>.</p><h2 id="search-and-appearance-preferences" tabindex="-1">Search and Appearance Preferences <a class="header-anchor" href="#search-and-appearance-preferences" aria-label="Permalink to &quot;Search and Appearance Preferences&quot;">​</a></h2><p>Documentation search runs locally in the browser. VitePress can use browser storage to remember preferences such as the appearance (dark or light theme). The documentation does not intentionally embed analytics, advertising trackers or third-party marketing scripts.</p><h2 id="consent-and-cookie-banner" tabindex="-1">Consent and Cookie Banner <a class="header-anchor" href="#consent-and-cookie-banner" aria-label="Permalink to &quot;Consent and Cookie Banner&quot;">​</a></h2><p>This documentation displays an informational notice about essential cookies and local storage. It does not request advertising or analytics consent because these optional services are not integrated. The notice is dismissed using a browser local-storage preference; technical and strictly necessary security storage may be used to deliver the requested service.</p><p>If optional tracking, external embeds or other non-essential technologies are added, the consent requirements must be reassessed <strong>before</strong> activation. Actual cookies and network requests should be reviewed whenever the hosting or Cloudflare proxy configuration changes.</p><h2 id="external-websites" tabindex="-1">External Websites <a class="header-anchor" href="#external-websites" aria-label="Permalink to &quot;External Websites&quot;">​</a></h2><p>Links to the Deblx website, Changelog, Help Center, Fab, GitHub and Discord point to external services. Their privacy practices apply when you follow those links.</p><h2 id="privacy-policy-and-contact" tabindex="-1">Privacy Policy and Contact <a class="header-anchor" href="#privacy-policy-and-contact" aria-label="Permalink to &quot;Privacy Policy and Contact&quot;">​</a></h2><ul><li><a href="https://deblx.com/privacy-policy" target="_blank" rel="noreferrer">Full Deblx Privacy Policy</a></li><li><a href="https://deblx.com/help" target="_blank" rel="noreferrer">Deblx Support</a></li></ul>',18)])])}const b=a(n,[["render",i]]);export{u as __pageData,b as default};
